def transform(grid):
    h, w = len(grid), len(grid[0])

    div_rows = [r for r in range(h)
                if all(v == grid[r][0] for v in grid[r]) and
                sum(v != 0 for v in grid[r]) == w and len(set(grid[r])) == 1]
    # Find full-height single-color divider columns.
    div_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1]

    def bands(n, divs):
        result = []
        start = 0
        for x in divs:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < n:
            result.append((start, n))
        return result

    # Dividers are solid lines, which need not have the same color as the background.
    row_bands = bands(h, div_rows)
    col_bands = bands(w, div_cols)

    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    best = None
    best_count = -1
    for ri, (ra, rb) in enumerate(row_bands):
        for ci, (ca, cb) in enumerate(col_bands):
            count = sum(grid[r][c] != bg
                        for r in range(ra, rb) for c in range(ca, cb))
            if count > best_count:
                best_count = count
                best = (ra, rb, ca, cb)

    ra, rb, ca, cb = best
    tile = [row[ca:cb] for row in grid[ra:rb]]
    out = [row[:] for row in grid]
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = tile[(r - r0) % len(tile)][(c - c0) % len(tile[0])]
    return out
